 if len(b.overflow) == 0 || b.cfg.Clock.Now().Before(b.overflowAt.Add(b.cfg.GracePeriod)) { return }
 for c := range b.cursors {
  if c.next < b.start {
   c.failed = true
   close(c.done)
   delete(b.cursors, c)
  }
 }
}
